"""XORE — FastAPI/Vercel/Google YouTube control center."""
from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, JSONResponse, RedirectResponse
from fastapi.middleware.cors import CORSMiddleware
from urllib.parse import urlencode
from datetime import datetime, timezone
import base64, hashlib, hmac, html, json, logging, os, secrets, time
import requests
from google.oauth2.credentials import Credentials
from googleapiclient.discovery import build
from google.auth.transport.requests import Request as GoogleRequest

try:
    from supabase import create_client
except Exception:
    create_client = None

app = FastAPI(title="XORE", version="3.0.0")
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=False, allow_methods=["*"], allow_headers=["*"])

# ============================================================================
# XORE IMMUTABLE CONFIG
# ============================================================================
COMMENT_TEXT = "اذكرو الله واستغفرو.🫀"
DEFAULT_MUSLIM_REPLY = "الله يجزاك خير"
DEFAULT_MUSLIM_WELCOME = "حياك الله نورت"
DEFAULT_MUSLIM_FRIDAY = "لا تنسون الصلاة على النبي ﷺ"

GOOGLE_CLIENT_ID = os.getenv("GOOGLE_CLIENT_ID", "").strip()
GOOGLE_CLIENT_SECRET = os.getenv("GOOGLE_CLIENT_SECRET", "").strip()
GOOGLE_REDIRECT_URI = os.getenv("GOOGLE_REDIRECT_URI", "").strip()
SUPABASE_URL = os.getenv("SUPABASE_URL", "").strip()
SUPABASE_SERVICE_ROLE_KEY = os.getenv("SUPABASE_SERVICE_ROLE_KEY", "").strip()
XORE_SESSION_SECRET = os.getenv("XORE_SESSION_SECRET", "") or secrets.token_urlsafe(48)

GOOGLE_SCOPES = [
    "https://www.googleapis.com/auth/youtube.force-ssl",
    "https://www.googleapis.com/auth/youtube.readonly",
]

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("xore")
supabase = None
if create_client and SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY:
    try:
        supabase = create_client(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY)
    except Exception:
        logger.exception("Supabase initialization failed")

# ============================================================================
# SUPABASE TABLE SQL
# ============================================================================
SUPABASE_SQL = """
create table if not exists public.xore_connections (
  id bigint generated by default as identity primary key,
  google_sub text unique not null,
  email text default '',
  channel_id text default '',
  channel_title text default '',
  refresh_token text not null,
  access_token text default '',
  token_expiry bigint default 0,
  mode text default 'muslim',
  enabled boolean default true,
  last_comment_video_id text default '',
  last_comment_at timestamptz null,
  last_error text default '',
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
create index if not exists xore_connections_enabled_idx on public.xore_connections(enabled);
alter table public.xore_connections enable row level security;
"""

# ============================================================================
# HELPERS
# ============================================================================
def iso_now():
    return datetime.now(timezone.utc).isoformat()

def jr(data, status=200):
    return JSONResponse(content=data, status_code=status)

def safe(value, limit=2000):
    return str(value or "").strip()[:limit]

def google_ready():
    return bool(GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET and GOOGLE_REDIRECT_URI)

def db_ready():
    return supabase is not None

def sign(value):
    mac = hmac.new(XORE_SESSION_SECRET.encode(), value.encode(), hashlib.sha256).digest()
    return value + "." + base64.urlsafe_b64encode(mac).decode().rstrip("=")

def verify(value):
    try:
        raw, signature = value.rsplit(".", 1)
        expected = sign(raw).rsplit(".", 1)[1]
        if hmac.compare_digest(signature, expected):
            return raw
    except Exception:
        pass
    return None

def session_user(request: Request):
    return verify(request.cookies.get("xore_session", ""))

# ============================================================================
# SUPABASE PERSISTENCE
# ============================================================================
def db_get(google_sub):
    if not supabase or not google_sub:
        return None
    try:
        result = supabase.table("xore_connections").select("*").eq("google_sub", google_sub).limit(1).execute()
        return (result.data or [None])[0]
    except Exception:
        logger.exception("db_get failed")
        return None

def db_upsert(row):
    if not supabase:
        return None
    try:
        result = supabase.table("xore_connections").upsert(row, on_conflict="google_sub").execute()
        return (result.data or [row])[0]
    except Exception:
        logger.exception("db_upsert failed")
        return None

def db_update(google_sub, patch):
    if not supabase or not google_sub:
        return False
    try:
        supabase.table("xore_connections").update(patch).eq("google_sub", google_sub).execute()
        return True
    except Exception:
        logger.exception("db_update failed")
        return False

def db_enabled():
    if not supabase:
        return []
    try:
        result = supabase.table("xore_connections").select("*").eq("enabled", True).execute()
        return result.data or []
    except Exception:
        logger.exception("db_enabled failed")
        return []

# ============================================================================
# GOOGLE OAUTH
# ============================================================================
def make_state(mode):
    payload = {
        "nonce": secrets.token_urlsafe(28),
        "mode": "muslim" if mode == "muslim" else "normal",
        "ts": int(time.time()),
    }
    raw = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode()).decode().rstrip("=")
    return sign(raw)

def decode_state(state):
    raw = verify(state or "")
    if not raw:
        return None
    try:
        padded = raw + "=" * ((4 - len(raw) % 4) % 4)
        payload = json.loads(base64.urlsafe_b64decode(padded.encode()).decode())
        if int(time.time()) - int(payload.get("ts", 0)) > 600:
            return None
        return payload
    except Exception:
        return None

def authorize_url(state):
    params = {
        "client_id": GOOGLE_CLIENT_ID,
        "redirect_uri": GOOGLE_REDIRECT_URI,
        "response_type": "code",
        "scope": " ".join(GOOGLE_SCOPES),
        "access_type": "offline",
        "prompt": "consent",
        "state": state,
    }
    return "https://accounts.google.com/o/oauth2/v2/auth?" + urlencode(params)

def exchange_google_code(code):
    response = requests.post(
        "https://oauth2.googleapis.com/token",
        data={
            "code": code,
            "client_id": GOOGLE_CLIENT_ID,
            "client_secret": GOOGLE_CLIENT_SECRET,
            "redirect_uri": GOOGLE_REDIRECT_URI,
            "grant_type": "authorization_code",
        },
        timeout=25,
    )
    response.raise_for_status()
    return response.json()

def google_profile(access_token):
    response = requests.get(
        "https://www.googleapis.com/oauth2/v3/userinfo",
        headers={"Authorization": "Bearer " + access_token},
        timeout=20,
    )
    response.raise_for_status()
    return response.json()

def youtube_client(credentials):
    return build("youtube", "v3", credentials=credentials, cache_discovery=False)

def channel_info(youtube):
    result = youtube.channels().list(part="id,snippet,contentDetails", mine=True).execute()
    items = result.get("items", [])
    if not items:
        raise RuntimeError("لم يتم العثور على قناة YouTube في الحساب.")
    return items[0]

def credentials_from_row(row):
    expiry = None
    if row.get("token_expiry"):
        try:
            expiry = datetime.fromtimestamp(int(row["token_expiry"]), timezone.utc)
        except Exception:
            expiry = None
    credentials = Credentials(
        token=row.get("access_token") or None,
        refresh_token=row.get("refresh_token") or None,
        token_uri="https://oauth2.googleapis.com/token",
        client_id=GOOGLE_CLIENT_ID,
        client_secret=GOOGLE_CLIENT_SECRET,
        scopes=GOOGLE_SCOPES,
        expiry=expiry,
    )
    if credentials.expired and credentials.refresh_token:
        credentials.refresh(GoogleRequest())
        db_update(row["google_sub"], {
            "access_token": credentials.token or "",
            "token_expiry": int(credentials.expiry.timestamp()) if credentials.expiry else 0,
            "updated_at": iso_now(),
        })
    return credentials

def latest_upload(youtube, uploads_playlist):
    result = youtube.playlistItems().list(
        part="snippet,contentDetails",
        playlistId=uploads_playlist,
        maxResults=10,
    ).execute()
    for item in result.get("items", []):
        video_id = item.get("contentDetails", {}).get("videoId")
        if video_id:
            return video_id
    return None

def create_fixed_comment(youtube, video_id):
    # This exact literal is the only allowed automated comment.
    if COMMENT_TEXT != "اذكرو الله واستغفرو.🫀":
        raise RuntimeError("Immutable comment check failed")
    return youtube.commentThreads().insert(
        part="snippet",
        body={
            "snippet": {
                "videoId": video_id,
                "topLevelComment": {
                    "snippet": {"textOriginal": COMMENT_TEXT}
                },
            }
        },
    ).execute()

def run_connection(row):
    if row.get("mode") != "muslim":
        return {"ok": True, "skipped": True, "reason": "non-muslim"}
    if not row.get("enabled", True):
        return {"ok": True, "skipped": True, "reason": "disabled"}

    credentials = credentials_from_row(row)
    youtube = youtube_client(credentials)
    channel = channel_info(youtube)
    uploads = channel.get("contentDetails", {}).get("relatedPlaylists", {}).get("uploads", "")
    if not uploads:
        raise RuntimeError("لم يتم العثور على Uploads playlist.")

    video_id = latest_upload(youtube, uploads)
    if not video_id:
        raise RuntimeError("لم يتم العثور على فيديو في القناة.")

    if row.get("last_comment_video_id") == video_id:
        return {"ok": True, "skipped": True, "reason": "already-commented", "video_id": video_id}

    create_fixed_comment(youtube, video_id)
    db_update(row["google_sub"], {
        "channel_id": channel.get("id", ""),
        "channel_title": channel.get("snippet", {}).get("title", ""),
        "last_comment_video_id": video_id,
        "last_comment_at": iso_now(),
        "last_error": "",
        "updated_at": iso_now(),
    })
    return {
        "ok": True,
        "skipped": False,
        "video_id": video_id,
        "channel_title": channel.get("snippet", {}).get("title", ""),
        "comment": COMMENT_TEXT,
    }

# ============================================================================
# ROUTES
# ============================================================================
@app.get("/", response_class=HTMLResponse)
async def home():
    return HTMLResponse(HTML_PAGE)

@app.get("/api/auth")
async def auth(request: Request):
    if request.query_params.get("mode") == "url":
        if not google_ready():
            return jr({"ok": False, "google_oauth_configured": False, "message": "أضف GOOGLE_CLIENT_ID و GOOGLE_CLIENT_SECRET و GOOGLE_REDIRECT_URI في Vercel."}, 503)
        selected = "muslim" if request.query_params.get("isMuslim") != "false" else "normal"
        state = make_state(selected)
        response = jr({"ok": True, "google_oauth_configured": True, "authorize_url": authorize_url(state)})
        response.set_cookie("xore_oauth_state", state, max_age=600, httponly=True, secure=True, samesite="lax")
        return response
    return jr({"ok": True, "app": "XORE", "google_oauth_configured": google_ready(), "supabase_configured": db_ready(), "server_time": iso_now()})

@app.get("/api/callback")
async def callback(request: Request):
    if request.query_params.get("error"):
        return HTMLResponse("<h1>XORE</h1><p>تم إلغاء ربط Google.</p>", status_code=400)
    state = request.query_params.get("state", "")
    cookie_state = request.cookies.get("xore_oauth_state", "")
    state_data = decode_state(state)
    if not state_data or not cookie_state or not hmac.compare_digest(state, cookie_state):
        return HTMLResponse("<h1>XORE</h1><p>جلسة OAuth غير صالحة أو منتهية.</p>", status_code=400)
    if not db_ready():
        return HTMLResponse("<h1>XORE</h1><p>Supabase غير مضبوط في Vercel.</p>", status_code=500)
    try:
        token = exchange_google_code(request.query_params.get("code", ""))
        access_token = token.get("access_token", "")
        refresh_token = token.get("refresh_token", "")
        if not access_token:
            raise RuntimeError("Google لم يعط Access Token")

        profile = google_profile(access_token)
        google_sub = safe(profile.get("sub"), 300)
        if not google_sub:
            raise RuntimeError("Google account id missing")

        credentials = Credentials(
            token=access_token,
            refresh_token=refresh_token or None,
            token_uri="https://oauth2.googleapis.com/token",
            client_id=GOOGLE_CLIENT_ID,
            client_secret=GOOGLE_CLIENT_SECRET,
            scopes=GOOGLE_SCOPES,
        )
        channel = channel_info(youtube_client(credentials))
        previous = db_get(google_sub)
        refresh_token = refresh_token or (previous or {}).get("refresh_token", "")
        if not refresh_token:
            raise RuntimeError("لم يتم الحصول على refresh token. احذف صلاحية XORE من حساب Google ثم أعد الربط.")

        db_upsert({
            "google_sub": google_sub,
            "email": safe(profile.get("email"), 300),
            "channel_id": safe(channel.get("id"), 300),
            "channel_title": safe(channel.get("snippet", {}).get("title"), 500),
            "refresh_token": refresh_token,
            "access_token": access_token,
            "token_expiry": int(credentials.expiry.timestamp()) if credentials.expiry else 0,
            "mode": state_data.get("mode", "muslim"),
            "enabled": True,
            "last_comment_video_id": (previous or {}).get("last_comment_video_id", ""),
            "last_comment_at": (previous or {}).get("last_comment_at"),
            "last_error": "",
            "updated_at": iso_now(),
        })

        response = RedirectResponse("/", status_code=303)
        response.delete_cookie("xore_oauth_state")
        response.set_cookie("xore_session", sign(google_sub), max_age=2592000, httponly=True, secure=True, samesite="lax")
        return response
    except Exception as exc:
        logger.exception("OAuth callback failed")
        return HTMLResponse(f"<h1>XORE</h1><p>فشل ربط YouTube: {html.escape(str(exc))}</p><p><a href='/'>رجوع</a></p>", status_code=500)

@app.get("/api/status")
async def status(request: Request):
    sub = session_user(request)
    row = db_get(sub) if sub else None
    return jr({
        "server_online": True,
        "google_oauth_configured": google_ready(),
        "supabase_configured": db_ready(),
        "connected": bool(row),
        "mode": row.get("mode", "muslim") if row else "muslim",
        "enabled": bool(row.get("enabled", True)) if row else False,
        "channel": row.get("channel_title", "") if row else "",
        "last_comment_at": row.get("last_comment_at") if row else None,
        "last_error": row.get("last_error", "") if row else "",
        "fixed_comment": COMMENT_TEXT,
    })

@app.post("/api/settings")
async def settings(request: Request):
    sub = session_user(request)
    if not sub:
        return jr({"ok": False, "error": "اربط Google أولاً."}, 401)
    row = db_get(sub)
    if not row:
        return jr({"ok": False, "error": "الحساب غير موجود."}, 404)
    try:
        data = await request.json()
    except Exception:
        data = {}
    mode = "muslim" if data.get("mode") == "muslim" else "normal"
    enabled = bool(data.get("enabled", row.get("enabled", True)))
    db_update(sub, {"mode": mode, "enabled": enabled, "updated_at": iso_now()})
    return jr({"ok": True, "mode": mode, "enabled": enabled, "fixed_comment": COMMENT_TEXT if mode == "muslim" else None})

@app.post("/api/logout")
async def logout():
    response = jr({"ok": True})
    response.delete_cookie("xore_session")
    return response

@app.get("/api/setup-info")
async def setup_info():
    return jr({"google_oauth_configured": google_ready(), "supabase_configured": db_ready(), "fixed_comment": COMMENT_TEXT, "supabase_sql": SUPABASE_SQL})

@app.api_route("/api/cron", methods=["GET", "POST"])
async def cron(request: Request):
    results = []
    rows = db_enabled()
    for row in rows:
        try:
            results.append({"google_sub": row.get("google_sub", ""), **run_connection(row)})
        except Exception as exc:
            error = safe(str(exc), 2000)
            db_update(row.get("google_sub", ""), {"last_error": error, "updated_at": iso_now()})
            results.append({"google_sub": row.get("google_sub", ""), "ok": False, "error": error})
    return jr({"ok": True, "server_time": iso_now(), "fixed_comment": COMMENT_TEXT, "count": len(rows), "results": results})

@app.get("/health")
async def health():
    return jr({"ok": True, "service": "XORE", "time": iso_now()})

